import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.CuUVYbLV.js";const b=JSON.parse('{"title":"兼容性","description":"rolebox 与 opencode / pi / dsh 的兼容性参考——平台能力矩阵、工具面、harness 版本约束、功能矩阵、运行时依赖与已知边界","frontmatter":{"title":"兼容性","description":"rolebox 与 opencode / pi / dsh 的兼容性参考——平台能力矩阵、工具面、harness 版本约束、功能矩阵、运行时依赖与已知边界"},"headers":[],"relativePath":"04-Advanced/compatibility.md","filePath":"04-Advanced/compatibility.md"}'),r={name:"04-Advanced/compatibility.md"};function s(n,t,c,i,l,h){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="兼容性-compatibility" tabindex="-1">兼容性（Compatibility） <a class="header-anchor" href="#兼容性-compatibility" aria-label="Permalink to &quot;兼容性（Compatibility）&quot;">​</a></h1><p>本页回答「这个功能在我用的 harness 上能不能用、需要什么版本」。内容按维度组织：平台能力开关、工具面、harness 版本约束、功能引入版本、运行时依赖、操作系统支持与已知兼容边界。安装命令与目录布局见<a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a>；破坏性变更与升级步骤见<a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a>。</p><blockquote><p>相关：<a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a>｜<a href="/rolebox-docs/03-Reference/limitations.html">已知限制</a>｜<a href="/rolebox-docs/03-Reference/cli.html">CLI 参考</a></p></blockquote><h2 id="快速核对" tabindex="-1">快速核对 <a class="header-anchor" href="#快速核对" aria-label="Permalink to &quot;快速核对&quot;">​</a></h2><p><code>rolebox status</code> 按平台注册表逐个报告 harness 的集成状态与同步落点，是核对本机兼容性的第一条命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，随环境略有差异）：</span></span>
<span class="line"><span>Rolebox v1.9.0</span></span>
<span class="line"><span>  Configuration</span></span>
<span class="line"><span>    Config               &lt;rolebox 配置目录&gt;/config.json</span></span>
<span class="line"><span>    Registries           &lt;注册中心列表&gt;</span></span>
<span class="line"><span>  Installed Roles</span></span>
<span class="line"><span>    ✓ &lt;角色名&gt;  &lt;版本&gt;  (&lt;注册中心&gt;)  → synced</span></span>
<span class="line"><span>  OpenCode Integration</span></span>
<span class="line"><span>    Plugin               ✓ registered</span></span>
<span class="line"><span>    Sync target          ~/.config/opencode/rolebox</span></span>
<span class="line"><span>  pi Integration (not detected)</span></span>
<span class="line"><span>    Sync target          ~/.pi/agent/rolebox</span></span>
<span class="line"><span>  dsh Integration (not detected)</span></span>
<span class="line"><span>    Sync target          ~/.dsh/rolebox</span></span></code></pre></div><p>只有 opencode 能报告「已注册/未注册」；pi 与 dsh 没有 rolebox 自己拥有的单一清单文件，因此只报告同步落点。</p><h2 id="平台能力矩阵-platform-capabilities" tabindex="-1">平台能力矩阵（Platform Capabilities） <a class="header-anchor" href="#平台能力矩阵-platform-capabilities" aria-label="Permalink to &quot;平台能力矩阵（Platform Capabilities）&quot;">​</a></h2><p>rolebox 用一组**能力开关（PlatformCapabilities，宿主声明自己支持哪些操作的布尔集合）**描述宿主差异，同一份核心代码据此优雅降级，而不是为每个 harness 分叉逻辑。</p><table tabindex="0"><thead><tr><th>能力开关</th><th>opencode</th><th>pi</th><th>dsh</th><th>含义</th></tr></thead><tbody><tr><td><code>hasBackgroundTasks</code></td><td>✅</td><td>✅</td><td>❌</td><td>后台/异步任务调度</td></tr><tr><td><code>hasSessionFork</code></td><td>✅</td><td>❌</td><td>✅</td><td>会话分叉/分支</td></tr><tr><td><code>hasSessionCreate</code></td><td>✅</td><td>❌</td><td>✅</td><td>新建会话</td></tr><tr><td><code>hasSessionAbort</code></td><td>✅</td><td>✅</td><td>❌</td><td>中止会话</td></tr><tr><td><code>hasAgentFileSync</code></td><td>✅</td><td>❌</td><td>❌</td><td>agent 文件注册</td></tr><tr><td><code>hasMultiStepTools</code></td><td>✅</td><td>✅</td><td>✅</td><td>多步工具执行</td></tr><tr><td><code>hasEventStream</code></td><td>✅</td><td>✅</td><td>✅</td><td>事件流</td></tr><tr><td><code>hasSessionStatus</code></td><td>✅</td><td>✅</td><td>✅</td><td>会话状态轮询</td></tr><tr><td><code>hasRoleSwitch</code></td><td>❌</td><td>✅</td><td>✅</td><td>会话内切换活动角色</td></tr></tbody></table><p><strong>能力开关目前是「声明」而非「门禁」</strong>：工具装配阶段并不读取这组值，因此能力矩阵用于解释行为差异，不能替代逐工具的可用性核对。</p><h2 id="工具面-tool-surface" tabindex="-1">工具面（Tool Surface） <a class="header-anchor" href="#工具面-tool-surface" aria-label="Permalink to &quot;工具面（Tool Surface）&quot;">​</a></h2><p>三个 harness 都消费同一套<strong>规范工具集（canonical tools，跨 harness 共享的公共工具面）</strong>，平台差异通过额外的工具注入实现。</p><h3 id="共享工具面" tabindex="-1">共享工具面 <a class="header-anchor" href="#共享工具面" aria-label="Permalink to &quot;共享工具面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具组</th><th>工具</th></tr></thead><tbody><tr><td>Hashline 编辑</td><td><code>hashline_read</code> / <code>hashline_edit</code></td></tr><tr><td>记忆</td><td><code>memory_write</code> / <code>memory_recall</code> / <code>memory_list</code></td></tr><tr><td>Web</td><td><code>web_search</code> / <code>web_read</code> / <code>web_fetch</code></td></tr><tr><td>控制与终端</td><td><code>signal</code> / <code>interactive_terminal</code></td></tr><tr><td>Asset 与引用</td><td><code>asset_search</code> / <code>asset_inspect</code> / <code>asset_validate</code> / <code>reference_search</code></td></tr><tr><td>会话（需要会话客户端）</td><td><code>session_list</code> / <code>session_read</code> / <code>session_search</code> / <code>session_info</code> / <code>session_diff</code> / <code>session_fork</code></td></tr><tr><td>图编排（需要调度管理器或平台图工具集）</td><td><code>graph_create</code> / <code>graph_add_node</code> / <code>graph_add_edge</code> / <code>graph_add_loop</code> / <code>graph_run</code> / <code>graph_status</code> / <code>graph_cancel</code> / <code>graph_approve</code></td></tr></tbody></table><h3 id="harness-专属与编排工具" tabindex="-1">harness 专属与编排工具 <a class="header-anchor" href="#harness-专属与编排工具" aria-label="Permalink to &quot;harness 专属与编排工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具组</th><th>opencode</th><th>pi</th><th>dsh</th></tr></thead><tbody><tr><td><code>memory_update</code></td><td>✅</td><td>✅</td><td>❌ 未装配</td></tr><tr><td><code>function_graph</code> / <code>skill_compose</code> / <code>context_assemble</code></td><td>✅</td><td>✅</td><td>❌ 未装配</td></tr><tr><td><code>lsp_*</code>（32 个语言服务器工具）</td><td>✅</td><td>✅</td><td>❌ 未装配</td></tr><tr><td><code>asset_hot_reload</code></td><td>✅</td><td>❌ opencode 专属</td><td>❌</td></tr><tr><td><code>load_role_skill</code></td><td>❌ opencode 有原生 skill 工具</td><td>✅ pi 专属</td><td>❌</td></tr><tr><td><code>task_*</code> 兼容层</td><td>✅</td><td>✅</td><td>❌ 未装配</td></tr><tr><td><code>dispatch_*</code></td><td>❌ 禁用，编排图化</td><td>❌ 不注册</td><td>❌ 未装配</td></tr><tr><td><code>loop_*</code></td><td>❌ 禁用，由 <code>graph_add_loop</code> 取代</td><td>❌ 禁用</td><td>✅ 仍注册</td></tr></tbody></table><p><code>task_retry</code> 在装配 <code>task_*</code> 的两个平台上都被刻意扣留：它会绕过图引擎的预算与审批门。</p><h3 id="引擎状态持久化差异" tabindex="-1">引擎状态持久化差异 <a class="header-anchor" href="#引擎状态持久化差异" aria-label="Permalink to &quot;引擎状态持久化差异&quot;">​</a></h3><p><code>graph_*</code> 引擎的持久化范围随 harness 而异：</p><table tabindex="0"><thead><tr><th>harness</th><th>引擎状态</th></tr></thead><tbody><tr><td>opencode</td><td><strong>完全内存运行</strong>：状态不写入 <code>.rolebox/state/engine-*.json</code>，没有跨会话恢复扫描，也不写 graph 事件日志；图的生命周期限定在创建它的进程内</td></tr><tr><td>pi</td><td>传入状态目录并接上启动恢复扫描与事件记录器，状态落在 <code>.rolebox/state</code></td></tr><tr><td>dsh</td><td>传入状态目录，状态落在 <code>.rolebox/state</code>；插件启动时另外执行 loop 状态恢复</td></tr></tbody></table><h2 id="harness-版本约束" tabindex="-1">harness 版本约束 <a class="header-anchor" href="#harness-版本约束" aria-label="Permalink to &quot;harness 版本约束&quot;">​</a></h2><table tabindex="0"><thead><tr><th>harness</th><th>声明位置</th><th>约束</th></tr></thead><tbody><tr><td>opencode</td><td><code>package.json</code> 的 <code>engines.opencode</code></td><td><code>^1.0.0</code></td></tr><tr><td>opencode</td><td><code>package.json</code> 的 <code>peerDependencies[&quot;@opencode-ai/plugin&quot;]</code></td><td><code>^1.3.0</code></td></tr><tr><td>pi</td><td><code>peerDependencies[&quot;@earendil-works/pi-coding-agent&quot;]</code></td><td><code>&gt;=0.70.0</code>（可选 peer）</td></tr><tr><td>dsh</td><td><code>peerDependencies[&quot;@deepseek-ai/cordis&quot;]</code></td><td><code>4.0.2</code>（可选 peer）</td></tr></tbody></table><p>早于 v1.0.0 的文档给出过按 rolebox 版本递增的 opencode 最低版本表（如 v0.17.x → opencode ≥1.3.0）。当前仓库只声明上表约束，旧阈值不再作为安装前置条件。</p><h2 id="功能兼容矩阵-feature-matrix" tabindex="-1">功能兼容矩阵（Feature Matrix） <a class="header-anchor" href="#功能兼容矩阵-feature-matrix" aria-label="Permalink to &quot;功能兼容矩阵（Feature Matrix）&quot;">​</a></h2><p>下表列出各功能领域的引入版本与适用 harness。<strong>适用 harness</strong> 一列是重点：不默认「全部功能都属于 opencode」。</p><table tabindex="0"><thead><tr><th>功能领域</th><th>引入版本</th><th>适用 harness</th><th>说明</th></tr></thead><tbody><tr><td>角色 YAML 系统</td><td>v0.1.x（早于 CHANGELOG 记录）</td><td>三种</td><td><code>role.yaml</code> 加载与解析</td></tr><tr><td>Functions 函数系统</td><td>v0.2.0</td><td>三种</td><td>用竖线包裹函数名激活（如 plan、execute）</td></tr><tr><td>CLI 工具链（init / list / search / update / registry / sync）</td><td>v0.4.0</td><td>三种（CLI 层，与 harness 无关）</td><td>citty</td></tr><tr><td>子代理系统</td><td>v0.5.1</td><td>三种</td><td>命名 <code>{parent}--{child}</code></td></tr><tr><td>References 引用文档系统</td><td>v0.6.0</td><td>三种</td><td>递归发现 <code>references/</code></td></tr><tr><td>Dispatch 调度引擎（事件驱动）</td><td>v0.10.0</td><td>三种</td><td><code>TaskWatchdogManager</code>；dsh 声明 <code>hasBackgroundTasks: false</code></td></tr><tr><td>Monitor 监控面板</td><td>v0.11.0</td><td>三种（交互 TUI 为 opencode 专属）</td><td>—</td></tr><tr><td>Loop 循环系统</td><td>v0.14.0</td><td>三种</td><td>有界循环组；硬上限参数为 <code>max_traversals</code></td></tr><tr><td>LSP 集成（32 个工具）</td><td>v0.17.0</td><td>opencode、pi</td><td>dsh 未装配</td></tr><tr><td>会话管理工具（6 个）</td><td>v0.17.0</td><td>三种</td><td>分叉能力：opencode ✅ / pi ❌ / dsh ✅</td></tr><tr><td>Hashline 内容哈希编辑</td><td>v0.17.0</td><td>三种</td><td>内容哈希锚点 + 文件版本守卫</td></tr><tr><td>模型重复预防</td><td>v0.18.0</td><td>三种</td><td>—</td></tr><tr><td>扩展系统与自定义 Hook</td><td>v0.19.0</td><td>opencode 完整、pi 非目标</td><td>pi 运行轻量服务栈</td></tr><tr><td>错误恢复框架</td><td>v0.19.0</td><td>opencode 完整、pi 非目标</td><td>pi 仅保留图引擎启动恢复</td></tr><tr><td>通知管理器</td><td>v0.19.0</td><td>三种</td><td>多通道、静默时段</td></tr><tr><td>持久记忆系统（SQLite + FTS5）</td><td>v0.20.0</td><td>三种</td><td>双运行时驱动（Bun / Node）</td></tr><tr><td>微内核架构与角色热重载</td><td>v0.20.0</td><td>opencode 完整、pi 非目标</td><td>pi 运行轻量服务栈</td></tr><tr><td>Token/成本预算管理</td><td>v0.20.0</td><td>三种</td><td>图级与节点级预算</td></tr><tr><td>TUI 仪表板（<code>rolebox monitor</code>）</td><td>v0.20.0</td><td>opencode（交互 TUI）</td><td>文本输出为 CLI 层</td></tr><tr><td>崩溃恢复</td><td>v0.21.0</td><td>三种</td><td>引擎状态持久化范围随 harness 而异</td></tr><tr><td>Asset 工具套件（search / inspect / validate）</td><td>v0.21.0</td><td>三种</td><td>—</td></tr><tr><td>web_fetch / web_read（多后端渲染）</td><td>v0.22.0</td><td>三种</td><td>Playwright / Crawlee 可选</td></tr><tr><td>Signal 带外控制信号</td><td>v0.22.0</td><td>三种</td><td>不嵌入文本内容</td></tr><tr><td>平台抽象层（<code>ISessionClient</code>）</td><td>v0.22.0</td><td>三种</td><td>ports-and-adapters</td></tr><tr><td>交互式终端工具</td><td>v1.4.0</td><td>三种</td><td>node-pty 可选，缺失时回退管道</td></tr><tr><td>pi 扩展与 dsh 插件</td><td>v1.2.0</td><td>pi、dsh</td><td>各自的宿主入口模块</td></tr><tr><td>pi / dsh 作为 CLI 同步目标</td><td>v1.3.0</td><td>三种</td><td><code>rolebox sync &lt;target&gt;</code></td></tr><tr><td>引擎 <code>&lt;graph_state&gt;</code> 提示块与 <code>graph:</code> 角色配置键</td><td>v1.8.0</td><td>三种</td><td>v2 引擎系统提示块</td></tr><tr><td>dsh web 角色坞与监控面板</td><td>v1.5.0 / v1.9.0</td><td>dsh</td><td>cordis 插件 + 浏览器侧 bundle</td></tr></tbody></table><p>「pi 非目标」指热重载、扩展、恢复引擎与 TUI 是 pi 相对于 opencode 的显式缺口；完整清单见<a href="/rolebox-docs/03-Reference/limitations.html">已知限制</a>。</p><h2 id="运行时依赖" tabindex="-1">运行时依赖 <a class="header-anchor" href="#运行时依赖" aria-label="Permalink to &quot;运行时依赖&quot;">​</a></h2><table tabindex="0"><thead><tr><th>依赖</th><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>持久记忆（Bun 运行时）</td><td><code>bun:sqlite</code></td><td>动态导入</td></tr><tr><td>持久记忆（Node 运行时）</td><td><code>node:sqlite</code>，自 Node 22.5 起可用</td><td>动态导入；两条路径都不会在另一种运行时下于模块求值阶段崩溃</td></tr><tr><td>可选渲染后端</td><td><code>playwright</code> ≥1.40.0 或 <code>crawlee</code> ≥3.0.0</td><td>web 工具的页面渲染</td></tr><tr><td>可选终端后端</td><td><code>node-pty</code> ≥1.0.0</td><td><code>interactive_terminal</code>；缺失时回退管道</td></tr><tr><td>构建与测试</td><td><code>bun run build</code>、<code>bun test</code></td><td>仓库开发用，与运行时部署无关</td></tr></tbody></table><h2 id="操作系统支持" tabindex="-1">操作系统支持 <a class="header-anchor" href="#操作系统支持" aria-label="Permalink to &quot;操作系统支持&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>macOS</td><td>完整支持</td><td>CI 矩阵覆盖</td></tr><tr><td>Linux</td><td>完整支持</td><td>CI 矩阵覆盖</td></tr><tr><td>Windows</td><td>基本支持</td><td>CI 矩阵覆盖；历史上有多轮 Windows 可移植性修复</td></tr></tbody></table><p>CI 在 <code>ubuntu-latest</code> / <code>macos-latest</code> / <code>windows-latest</code> 三个 runner 上运行类型检查、构建与测试。少数依赖真实 <code>tar</code> 的安装测试在没有可用 <code>tar</code> 的宿主上会优雅跳过而不是让构建失败。Windows 的路径分隔符与符号链接行为仍可能与类 Unix 系统不同。</p><h2 id="已知兼容边界" tabindex="-1">已知兼容边界 <a class="header-anchor" href="#已知兼容边界" aria-label="Permalink to &quot;已知兼容边界&quot;">​</a></h2><ul><li><strong>会话内角色切换</strong>：opencode 不支持（<code>hasRoleSwitch: false</code>）；pi 与 dsh 支持（角色选择器与宿主路由）。</li><li><strong>子代理嵌套</strong>：基于文件系统的子代理支持递归嵌套，最大深度 3；子代理之间不能直接通信，所有协调经父角色进行。</li><li><strong>无角色继承</strong>：角色之间不支持继承关系，每个角色完全独立。</li><li><strong>pi 的平台固有缺口</strong>：热重载、扩展、恢复引擎与 TUI 在 pi 上为显式非目标——pi 运行轻量服务栈，而不是完整的微内核服务栈。</li></ul><h2 id="与-opencode-生态共存" tabindex="-1">与 opencode 生态共存 <a class="header-anchor" href="#与-opencode-生态共存" aria-label="Permalink to &quot;与 opencode 生态共存&quot;">​</a></h2><p>rolebox 与 <a href="https://github.com/code-yeongyu/oh-my-openagent" target="_blank" rel="noreferrer">oh-my-openagent</a> 可以同时运行：角色出现在 agent 列表中，技能可由原生 skill 工具发现，两者无冲突。这条共存说明只适用于 opencode——pi 与 dsh 不使用 opencode 的 agent/skill 发现机制，而是各自走扩展与 cordis 插件注册。</p><h2 id="破坏性变更与升级" tabindex="-1">破坏性变更与升级 <a class="header-anchor" href="#破坏性变更与升级" aria-label="Permalink to &quot;破坏性变更与升级&quot;">​</a></h2><p>本页不再重复破坏性变更清单与升级步骤：各版本的移除项、旧写法到新写法的对照，以及 v0.x 到 v1.9.0 的升级路径，统一见<a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a>。</p>`,40)])])}const g=d(r,[["render",s]]);export{b as __pageData,g as default};
